   108	function convertToDisplayString(amountInCents = 0, currency: string = CONST.CURRENCY.USD): string {
   109	    const convertedAmount = convertToFrontendAmountAsInteger(amountInCents, currency);
   110	    /**
   111	     * Fallback currency to USD if it empty string or undefined
