   121	        // We are forcing the number of decimals because we override the default number of decimals in the backend for some currencies
   122	        // See: https://github.com/Expensify/PHP-Libs/pull/834
   123	        minimumFractionDigits: getCurrencyDecimals(currency),
   124	        // For currencies that have decimal places > 2, floor to 2 instead as we don't support more than 2 decimal places.
   125	        maximumFractionDigits: 2,
